271:{"id": "v19/composite/char_female", "version": 1, "symbol": "char_female", "kind": "composite", "status": "Composite", "category": "character-property-value", "signature": "TERM char_female() -> TERM", "definition": "Female gender.", "aliases": ["female"], "expansion": "character_trait(property=\"gender\", value=\"female\")", "dependencies": ["v19/support/character_trait"], "shared_rules": ["v19/rule/composites-general", "v19/rule/category/character-property-value"]}
272:{"id": "v19/composite/char_age_14", "version": 2, "symbol": "char_age_14", "kind": "composite", "status": "Deprecated", "category": "character-property-value", "signature": "TERM char_age_14() -> TERM", "definition": "Age 14.", "aliases": ["14"], "expansion": "character_trait(property=\"age_years\", value=14)", "dependencies": ["v19/support/character_trait"], "shared_rules": ["v19/rule/composites-general", "v19/rule/category/character-property-value"], "superseded_by": ["v19/support/character_trait"], "deprecated": "use character_trait(property=\"age_years\", value=14); human decision 2026-10-04: sizes and amounts are a number plus a unit, built with a constructor; no symbol per value"}
293:{"id": "v19/support/character_trait", "version": 1, "symbol": "character_trait", "kind": "constructor", "status": "Retained", "signature": "TERM character_trait(property: STRING, value: STRING / NUMBER) -> TERM", "definition": "A character attribute", "not": "Not a claim about a real person", "shared_rules": ["v19/rule/support-primitives-general"]}
483:{"id": "v19/composite/char_age_18", "version": 2, "symbol": "char_age_18", "kind": "composite", "status": "Deprecated", "signature": "TERM char_age_18() -> TERM", "definition": "Age 18 character trait.", "not": "char_age_14 (which represents age 14)", "aliases": ["18", "over 18"], "expansion": "character_trait(property=\"age_years\", value=18)", "dependencies": ["v19/support/character_trait"], "shared_rules": ["v19/rule/composites-general"], "superseded_by": ["v19/support/character_trait"], "deprecated": "use character_trait(property=\"age_years\", value=18); human decision 2026-10-04: sizes and amounts are a number plus a unit, built with a constructor; no symbol per value"}
621:{"id": "v19/support/interpersonal_stance", "version": 1, "symbol": "interpersonal_stance", "kind": "constructor", "status": "Accepted", "signature": "TERM interpersonal_stance(actor: STRING / TERM, stance: STRING, target?: STRING / TERM) -> TERM", "definition": "Constructs a descriptive representation of an actor's interpersonal stance, level of commitment, or relational engagement toward a partner.", "not": "character_trait (fictional characters) or attitude (an asserted claim relation)", "aliases": ["relational_commitment", "interpersonal_behavior", "relationship_stance"], "shared_rules": ["v19/rule/support-primitives-general"]}
